mapper.sql:
where 1=1

		and cdpc_llave = #{llaveTabla}


		and cdpc_estado = #{estado}


		and cdpc_plantilla = #{plantilla}


		and cdpc_formato = #{formato}


		and cdpc_nombre = #{nombre}


		and cdpc_codigo = #{codigo}


		and (upper(cdpc_nombre) like upper('%' || #{filtroParametro} || '%'))

mapper.update:
update pedidoventa_pdvp 
set cpdv_descripcion = (select cpvc_valortext from pedidoventacaracteristica_pvcp where cpvc_documento = cpdv_llave and cpvc_estado = 'A' and cpvc_campo = #{pField} limit 1)null
where cpdv_plantilla = #{pTemplate}

mapper.select:
select count(*) from documentoplantillacaracteristica_dpcp dd 
	inner join propiedad_ppdp pp on pp.cppd_campo = dd.cdpc_llave and pp.cppd_estado = 'A'
where dd.cdpc_plantilla = #{plantilla} and dd.cdpc_estado = 'A'
	and pp.cppd_propiedadvalor = 'PROP_96'
	and pp.cppd_valor = #{llaveTabla}
	and dd.cdpc_llave != #{llaveTabla}
